export type BackstopPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function backstopProgram() {
  return <T extends BackstopPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { backstop: BackstopPlugin }> => {
    return extendClient(client, {
      backstop: {
        accounts: {
          backer: addSelfFetchFunctions(client, getBackerCodec()),
          backstopConfig: addSelfFetchFunctions(
            client,
            getBackstopConfigCodec(),
          ),
          badDebtCover: addSelfFetchFunctions(client, getBadDebtCoverCodec()),
          borrowerClaims: addSelfFetchFunctions(
            client,
            getBorrowerClaimsCodec(),
          ),
          claim: addSelfFetchFunctions(client, getClaimCodec()),
          interestAbsorbed: addSelfFetchFunctions(
            client,
            getInterestAbsorbedCodec(),
          ),
          inventory: addSelfFetchFunctions(client, getInventoryCodec()),
          overrideRequest: addSelfFetchFunctions(
            client,
            getOverrideRequestCodec(),
          ),
          revokedAttestation: addSelfFetchFunctions(
            client,
            getRevokedAttestationCodec(),
          ),
        },
        instructions: {
          absorbInterest: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAbsorbInterestInstructionAsync(input),
            ),
          approveOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getApproveOverrideInstructionAsync(input),
            ),
          buyInventory: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuyInventoryInstructionAsync(input),
            ),
          cancelClaim: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelClaimInstructionAsync(input),
            ),
          claimStream: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimStreamInstructionAsync(input),
            ),
          coverBadDebt: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCoverBadDebtInstructionAsync(input),
            ),
          deposit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getDepositInstructionAsync(input),
            ),
          expireQueued: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExpireQueuedInstructionAsync(input),
            ),
          expireStale: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getExpireStaleInstructionAsync(input),
            ),
          finalizeWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getFinalizeWithdrawInstructionAsync(input),
            ),
          initializeBackstop: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeBackstopInstructionAsync(input),
            ),
          openBacker: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenBackerInstructionAsync(input),
            ),
          openBadDebtCover: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenBadDebtCoverInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          openBorrowerClaims: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenBorrowerClaimsInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          openInterestAbsorbed: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenInterestAbsorbedInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          openInventory: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenInventoryInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          openOverride: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenOverrideInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          poolLiquidate: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPoolLiquidateInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          requestWithdraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRequestWithdrawInstructionAsync(input),
            ),
          revokeAttestation: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevokeAttestationInstructionAsync(input),
            ),
          setAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetAdminInstructionAsync(input),
            ),
          setBackstopParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetBackstopParamsInstructionAsync(input),
            ),
          setClaimTiming: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetClaimTimingInstructionAsync(input),
            ),
          setCoSigner: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetCoSignerInstructionAsync(input),
            ),
          setPoolLiquidationParams: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPoolLiquidationParamsInstructionAsync(input),
            ),
          setVerdictOracle: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetVerdictOracleInstructionAsync(input),
            ),
          submitFacts: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSubmitFactsInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          suspendClaim: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSuspendClaimInstructionAsync(input),
            ),
          tryReleaseQueued: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getTryReleaseQueuedInstructionAsync(input),
            ),
          unlockClaim: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUnlockClaimInstructionAsync(input),
            ),
          unsuspendClaim: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUnsuspendClaimInstructionAsync(input),
            ),
          writeOffInventory: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWriteOffInventoryInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          interestAbsorbed: findInterestAbsorbedPda,
          poolUsdcVault: findPoolUsdcVaultPda,
          claim: findClaimPda,
          overrideRequest: findOverrideRequestPda,
          inventory: findInventoryPda,
          inventoryVault: findInventoryVaultPda,
          cover: findCoverPda,
          backer: findBackerPda,
          borrowerClaims: findBorrowerClaimsPda,
          revoked: findRevokedPda,
        },
        identifyAccount: identifyBackstopAccount,
        identifyInstruction: identifyBackstopInstruction,
        parseInstruction: parseBackstopInstruction,
      } as BackstopPlugin,
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
